using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<int> b(n + 1);
        for (int i = 1; i <= n; i++) scanf("%d", &b[i]);
        vector<array<int, 3>> iv; // (R, L, idx)
        for (int i = 1; i <= n; i++) {
            int L, R;
            if (b[i] == 0) { L = i + 1; R = n; }
            else { L = i / (b[i] + 1) + 1; R = i / b[i]; }
            iv.push_back({R, L, i});
        }
        sort(iv.begin(), iv.end());
        set<int> freeV;
        for (int v = 1; v <= n; v++) freeV.insert(v);
        vector<int> a(n + 1);
        for (auto &x : iv) {
            auto it = freeV.lower_bound(x[1]);
            a[x[2]] = *it;
            freeV.erase(it);
        }
        for (int i = 1; i <= n; i++) printf("%d%c", a[i], i == n ? '\n' : ' ');
    }
}

