#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; ll c; scanf("%d %lld", &n, &c);
        vector<ll> a(n + 1), b(n + 1);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        // cost to use teleporter i after standing at 0 or n+1: min(i, n+1-i) + a_i
        for (int i = 1; i <= n; i++) {
            ll s = min<ll>(i, n + 1 - i);
            b[i] = s + a[i];
        }
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 1);
        sort(ord.begin(), ord.end(), [&](int x, int y) { return b[x] < b[y]; });
        vector<int> pos(n + 1);
        vector<ll> P(n + 1, 0); // P[k] = sum of k smallest b
        for (int k = 0; k < n; k++) { pos[ord[k]] = k; P[k + 1] = P[k] + b[ord[k]]; }
        int best = 0;
        for (int f = 1; f <= n; f++) {
            ll first = f + a[f];
            if (first > c) continue;
            ll budget = c - first;
            // sum of m smallest b excluding f
            auto sumExcl = [&](int m) -> ll {
                if (m <= pos[f]) return P[m];
                return P[m + 1] - b[f];
            };
            int lo = 0, hi = n - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (sumExcl(mid) <= budget) lo = mid; else hi = mid - 1;
            }
            best = max(best, 1 + lo);
        }
        printf("%d\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int cnt[4];
    for (int i = 0; i < 4; i++) scanf("%d", &cnt[i]);
    int total = cnt[0] + cnt[1] + cnt[2] + cnt[3];
    for (int s = 0; s < 4; s++) {
        if (cnt[s] == 0) continue;
        int rem[4];
        for (int i = 0; i < 4; i++) rem[i] = cnt[i];
        vector<int> seq;
        int cur = s;
        rem[cur]--; seq.push_back(cur);
        while ((int)seq.size() < total) {
            // prefer the lower neighbour, otherwise the upper one
            if (cur > 0 && rem[cur - 1] > 0) cur--;
            else if (cur < 3 && rem[cur + 1] > 0) cur++;
            else break;
            rem[cur]--; seq.push_back(cur);
        }
        if ((int)seq.size() == total) {
            printf("YES\n");
            for (int i = 0; i < total; i++) printf("%d%c", seq[i], i + 1 == total ? '\n' : ' ');
            return 0;
        }
    }
    printf("NO\n");
}

