#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, k; scanf("%d %d", &n, &k);
        vector<ll> a(n), b(n);
        for (auto &x : a) scanf("%lld", &x);
        for (auto &x : b) scanf("%lld", &x);
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int x, int y) { return b[x] > b[y]; });  // b descending
        vector<ll> suf(n + 1, 0);  // suf[p] = sum over positions >= p of max(0, b - a)
        for (int p = n - 1; p >= 0; p--) suf[p] = suf[p + 1] + max(0LL, b[ord[p]] - a[ord[p]]);
        if (k == 0) { printf("%lld\n", suf[0]); continue; }
        ll best = 0, pool = 0;          // pool: the k-1 smallest a among earlier positions
        priority_queue<ll> H;
        for (int p = 0; p < n; p++) {
            ll ap = a[ord[p]];
            if ((int)H.size() == k - 1) best = max(best, -(ap + pool) + suf[p + 1]);
            if (k - 1 > 0) {
                H.push(ap); pool += ap;
                if ((int)H.size() > k - 1) { pool -= H.top(); H.pop(); }
            }
        }
        printf("%lld\n", best);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n;
    scanf("%d", &n);
    vector<ll> s(n + 1);
    for (int i = 1; i <= n; i++) scanf("%lld", &s[i]);
    // BIT over values 1..n, storing the sum of values still unused
    vector<ll> bit(n + 1, 0);
    for (int v = 1; v <= n; v++) {
        bit[v] += v;
        int j = v + (v & -v);
        if (j <= n) bit[j] += bit[v];
    }
    int LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    vector<int> p(n + 1);
    for (int i = n; i >= 1; i--) {
        // smallest x with prefix sum (values <= x) > s_i; that x is p_i
        int pos = 0; ll rem = s[i];
        for (int k = LOG; k >= 0; k--) {
            int np = pos + (1 << k);
            if (np <= n && bit[np] <= rem) { pos = np; rem -= bit[np]; }
        }
        int x = pos + 1;
        p[i] = x;
        for (int j = x; j <= n; j += j & -j) bit[j] -= x;
    }
    for (int i = 1; i <= n; i++) printf("%d%c", p[i], i == n ? '\n' : ' ');
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, m; scanf("%d %d", &n, &m);
        vector<int> eu(m), ev(m), ew(m), tin(n + 1, -1), low(n + 1), pe(n + 1, -1), it(n + 1, 0);
        vector<vector<pair<int, int>>> adj(n + 1);
        for (int i = 0; i < m; i++) { scanf("%d %d %d", &eu[i], &ev[i], &ew[i]); adj[eu[i]].push_back({ev[i], i}); adj[ev[i]].push_back({eu[i], i}); }
        int timer = 0;  // iterative DFS: tin, low, pe = parent edge
        for (int s = 1; s <= n; s++) {
            if (tin[s] != -1) continue;
            vector<int> st = {s}; tin[s] = low[s] = timer++;
            while (!st.empty()) {
                int v = st.back();
                if (it[v] < (int)adj[v].size()) {
                    auto [to, id] = adj[v][it[v]++];
                    if (id == pe[v]) continue;
                    if (tin[to] == -1) { pe[to] = id; tin[to] = low[to] = timer++; st.push_back(to); }
                    else low[v] = min(low[v], tin[to]);
                } else {
                    st.pop_back();
                    if (pe[v] != -1) { int p = eu[pe[v]] ^ ev[pe[v]] ^ v; low[p] = min(low[p], low[v]); }
                }
            }
        }
        int best = -1;  // non-bridge: back edge, or tree edge whose child reaches above its parent
        for (int i = 0; i < m; i++) {
            bool tree = pe[eu[i]] == i || pe[ev[i]] == i; int c = pe[eu[i]] == i ? eu[i] : ev[i];
            if ((!tree || low[c] <= tin[eu[i] ^ ev[i] ^ c]) && (best < 0 || ew[i] < ew[best])) best = i;
        }
        vector<int> par(n + 1, -2), q = {eu[best]}, cyc; par[eu[best]] = -1;  // BFS eu -> ev, skip edge best
        for (size_t h = 0; h < q.size(); h++) for (auto [to, id] : adj[q[h]]) if (id != best && par[to] == -2) { par[to] = q[h]; q.push_back(to); }
        for (int x = ev[best]; x != -1; x = par[x]) cyc.push_back(x);
        reverse(cyc.begin(), cyc.end());
        printf("%d %d\n", ew[best], (int)cyc.size());
        for (size_t i = 0; i < cyc.size(); i++) printf("%d%c", cyc[i], i + 1 == cyc.size() ? '\n' : ' ');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n, x; scanf("%d %d", &n, &x);
        vector<int> p(n + 1, 0);
        for (int i = 1; i <= n; i++) { int a; scanf("%d", &a); p[i] = p[i - 1] ^ a; }
        // OR <= x  iff  OR is a submask of some S in the family below
        vector<int> fam = {x};
        for (int b = 0; b < 30; b++)
            if (x >> b & 1) fam.push_back((x & ~(1 << b)) | ((1 << b) - 1));
        int ans = -1;
        for (int S : fam) {
            // dp over prefix: segment (j, i] is valid iff p_i and p_j agree outside S
            unordered_map<int, int> best;
            best[0] = 0;  // p_0 = 0 has key 0
            int last = -1;
            for (int i = 1; i <= n; i++) {
                int key = p[i] & ~S, d = -1;
                auto it = best.find(key);
                if (it != best.end()) d = it->second + 1;
                if (i == n) last = d;
                if (d >= 0) {
                    auto jt = best.find(key);
                    if (jt == best.end()) best[key] = d;
                    else jt->second = max(jt->second, d);
                }
            }
            ans = max(ans, last);
        }
        printf("%d\n", ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
const int INF = 1e9;  // seg tree over values 1..n: slack of remaining b-values, INF elsewhere
vector<int> mn, lz;
void push(int o) { for (int c : {2*o, 2*o+1}) mn[c] += lz[o], lz[c] += lz[o]; lz[o] = 0; }
void upd(int o, int l, int r, int ql, int qr, int v) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { mn[o] += v; lz[o] += v; return; }
    push(o); int m = (l + r) / 2;
    upd(2*o, l, m, ql, qr, v); upd(2*o+1, m+1, r, ql, qr, v); mn[o] = min(mn[2*o], mn[2*o+1]);
}
int rightmost(int o, int l, int r, int R) {  // rightmost index <= R with slack <= 0, or -1
    if (l > R || mn[o] > 0) return -1;
    if (l == r) return l;
    push(o); int m = (l + r) / 2, res = rightmost(2*o+1, m+1, r, R);
    return res != -1 ? res : rightmost(2*o, l, m, R);
}
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n); int m = n / 2; bool ok = true;
        vector<int> b(m + 1), cnt(n + 2, 0), less(n + 2, 0), p(n + 1, 0);
        for (int i = 1; i <= m; i++) { scanf("%d", &b[i]); if (cnt[b[i]]++) ok = false; }
        for (int v = 1; v <= n + 1; v++) less[v] = less[v - 1] + cnt[v - 1];
        mn.assign(4 * n + 4, INF); lz.assign(4 * n + 4, 0);
        for (int v = 1; v <= n; v++) if (cnt[v]) {  // slack = free below v minus b-values <= v
            int s = (v - 1 - less[v]) - (less[v] + 1); if (s < 0) ok = false;
            upd(1, 1, n, v, v, s - INF);
        }
        set<int> freeSet; for (int v = 1; v <= n; v++) if (!cnt[v]) freeSet.insert(v);
        for (int i = 1; i <= m && ok; i++) {  // b_i gets the smallest free value above the last zero-slack b
            int bi = b[i], z = max(0, rightmost(1, 1, n, bi - 1)); auto it = freeSet.upper_bound(z);
            if (it == freeSet.end() || *it >= bi) { ok = false; break; }
            int f = *it; freeSet.erase(it); p[2*i-1] = f; p[2*i] = bi;
            upd(1, 1, n, f + 1, n, -1); upd(1, 1, n, bi, n, +1); upd(1, 1, n, bi, bi, INF);
        }
        if (!ok) puts("-1");
        else for (int i = 1; i <= n; i++) printf("%d%c", p[i], i == n ? '\n' : ' ');
    }
}

