        int n, q; scanf("%d %d", &n, &q);
        vector<int> a(n + 2), L(n + 2, 0), R(n + 2, 0), st;
        for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
        // L[j]: nearest i<j with a_i > a_j ; R[j]: nearest k>j with a_k < a_j (0 if none)
        for (int j = 1; j <= n; j++) {
            while (!st.empty() && a[st.back()] < a[j]) st.pop_back();
            L[j] = st.empty() ? 0 : st.back();
            st.push_back(j);
        }
        st.clear();
        for (int j = n; j >= 1; j--) {
            while (!st.empty() && a[st.back()] > a[j]) st.pop_back();
            R[j] = st.empty() ? 0 : st.back();
            st.push_back(j);
        }
        // a 321 pattern lies inside [l, r] iff some j has L[j] >= l and R[j] <= r
        vector<int> bestL(n + 2, 0);
        for (int j = 1; j <= n; j++)
            if (L[j] && R[j]) bestL[R[j]] = max(bestL[R[j]], L[j]);
        for (int r = 1; r <= n; r++) bestL[r] = max(bestL[r], bestL[r - 1]);
        while (q--) {
            int l, r; scanf("%d %d", &l, &r);
            puts(bestL[r] >= l ? "NO" : "YES");
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; ll m; scanf("%d %lld", &n, &m);
        vector<ll> l(n), r(n);
        for (int i = 0; i < n; i++) scanf("%lld %lld", &l[i], &r[i]);
        // answer = 2 * max_i (len_i - min_j |I_i & I_j|); the minimising j is one of three candidates:
        // A: min r over l_j <= l_i, B: max l over r_j >= r_i, C: shortest interval inside I_i
        vector<int> byL(n), byR(n);
        iota(byL.begin(), byL.end(), 0); sort(byL.begin(), byL.end(), [&](int x, int y) { return l[x] < l[y]; });
        iota(byR.begin(), byR.end(), 0); sort(byR.begin(), byR.end(), [&](int x, int y) { return r[x] < r[y]; });
        vector<ll> sl(n), sr(n), prefMinR(n), sufMaxL(n);
        for (int k = 0; k < n; k++) { sl[k] = l[byL[k]]; sr[k] = r[byR[k]]; }
        for (int k = 0; k < n; k++) prefMinR[k] = min(r[byL[k]], k ? prefMinR[k-1] : LLONG_MAX);
        for (int k = n - 1; k >= 0; k--) sufMaxL[k] = max(l[byR[k]], k + 1 < n ? sufMaxL[k+1] : LLONG_MIN);
        vector<ll> ur = sr; ur.erase(unique(ur.begin(), ur.end()), ur.end());
        int U = ur.size();
        vector<ll> bit(U + 1, LLONG_MAX);     // prefix-min BIT over compressed r, holding interval lengths
        auto ins = [&](int p, ll v) { for (; p <= U; p += p & -p) bit[p] = min(bit[p], v); };
        auto qry = [&](int p) { ll res = LLONG_MAX; for (; p > 0; p -= p & -p) res = min(res, bit[p]); return res; };
        ll best = 0;
        for (int k = n - 1; k >= 0; k--) {              // scan by l descending
            int j = byL[k];
            if (k == n - 1 || l[byL[k+1]] != l[j])     // insert the whole group of equal l first
                for (int q = k; q >= 0 && l[byL[q]] == l[j]; q--) {
                    int x = byL[q];
                    ins(lower_bound(ur.begin(), ur.end(), r[x]) - ur.begin() + 1, r[x] - l[x] + 1);
                }
            int i = j;
            ll A = max(0LL, min(r[i], prefMinR[upper_bound(sl.begin(), sl.end(), l[i]) - sl.begin() - 1]) - l[i] + 1);
            ll B = max(0LL, r[i] - max(l[i], sufMaxL[lower_bound(sr.begin(), sr.end(), r[i]) - sr.begin()]) + 1);
            ll C = qry(upper_bound(ur.begin(), ur.end(), r[i]) - ur.begin());
            best = max(best, r[i] - l[i] + 1 - min({A, B, C}));
        }
        printf("%lld\n", 2 * best);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n; vector<ll> cntB, sumB;  // BIT over ranks (segments sorted by length, longest first)
void add(int p, ll c, ll s) { for (; p <= n; p += p & -p) cntB[p] += c, sumB[p] += s; }
ll pref(vector<ll>& B, int p) { ll r = 0; for (; p > 0; p -= p & -p) r += B[p]; return r; }
int posOf(ll c) { int pos = 0; ll rem = c; for (int st = 1 << 18; st; st >>= 1) if (pos + st <= n && cntB[pos + st] < rem) { pos += st; rem -= cntB[pos]; } return pos + 1; }
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        ll k; scanf("%d %lld", &n, &k);
        vector<ll> l(n), r(n);
        for (auto &x : l) scanf("%lld", &x);
        for (auto &x : r) scanf("%lld", &x);
        vector<int> ord(n), rk(n); iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int x, int y) { return r[x] - l[x] > r[y] - l[y]; });
        for (int p = 0; p < n; p++) rk[ord[p]] = p + 1;
        ll len3 = 0; for (int i = 0; i < n; i++) len3 += (r[i] - l[i] + 1 >= 3);
        cntB.assign(n + 1, 0); sumB.assign(n + 1, 0);
        auto topSum = [&](ll c) { return c == 0 ? 0LL : pref(sumB, posOf(c)); };
        ll best = LLONG_MAX, C = 0;
        for (int j = 0; j < n; j++) {   // j = last segment used; its block ends at x
            ll lj = l[j], need = k + lj - 1 - r[j], cmin = 0;   // cmin: fewest earlier segments needed
            bool feas = need <= 0 || topSum(C) >= need;
            if (feas && need > 0) { ll lo = 0, hi = C; while (lo < hi) { ll m = (lo + hi) / 2; if (topSum(m) >= need) hi = m; else lo = m + 1; } cmin = lo; }
            if (feas) {
                ll C3 = min(C, pref(cntB, len3));          // candidates: cmin, C3, and the T1/T2 crossing
                auto cost = [&](ll c) { return max(lj + 2 + 2 * c, k + lj + 1 + 2 * c - topSum(c)); };
                ll hi = max(cmin, min(C3, C)), lo = cmin, up = hi;
                best = min({best, cost(cmin), cost(hi)});
                while (lo < up) { ll m = (lo + up) / 2; if (lj + 2 + 2 * m >= k + lj + 1 + 2 * m - topSum(m)) up = m; else lo = m + 1; }
                best = min(best, cost(lo));
            }
            add(rk[j], 1, r[j] - lj + 1); C++;
        }
        printf("%lld\n", best == LLONG_MAX ? -1 : best);
    }
}

#include <bits/stdc++.h>
