    while (t--) {
        int n, q; scanf("%d %d", &n, &q);
        static char buf[200005];
        scanf("%s", buf);
        set<int> ba, bc, ca, cb;                 // indices of operations of each type, in order
        for (int i = 0; i < q; i++) {
            char x, y; scanf(" %c %c", &x, &y);
            if (x == 'b' && y == 'a') ba.insert(i);
            if (x == 'b' && y == 'c') bc.insert(i);
            if (x == 'c' && y == 'a') ca.insert(i);
            if (x == 'c' && y == 'b') cb.insert(i);
        }
        string out;
        for (int p = 0; p < n; p++) {
            char ch = buf[p];
            if (ch == 'a') { out += 'a'; continue; }
            if (ch == 'b') {                     // b -> a: direct, else b->c then c->a
                if (!ba.empty()) { ba.erase(ba.begin()); out += 'a'; continue; }
                if (!bc.empty()) {
                    auto j = ca.upper_bound(*bc.begin());
                    if (j != ca.end()) { bc.erase(bc.begin()); ca.erase(j); out += 'a'; continue; }
                }
                out += 'b'; continue;
            }
            // ch == 'c': c -> a direct, else c->b then b->a, else c->b alone
            if (!ca.empty()) { ca.erase(ca.begin()); out += 'a'; continue; }
            if (!cb.empty()) {
                auto j = ba.upper_bound(*cb.begin());
                if (j != ba.end()) { cb.erase(cb.begin()); ba.erase(j); out += 'a'; continue; }
                cb.erase(prev(cb.end())); out += 'b'; continue;
            }
            out += 'c';
        }
        printf("%s\n", out.c_str());
    }
}

