        iota(par.begin(), par.end(), 0);
        ll best = LLONG_MAX;
        for (auto &[w, u, v] : e) {
            // add edges in increasing weight; the component of 1 and n, using all its edges, gives min + max = minW + w
            int a = find(u), b = find(v);
            if (a != b) { par[a] = b; mnW[b] = min(mnW[a], mnW[b]); }
            mnW[find(u)] = min(mnW[find(u)], w);
            if (find(1) == find(n)) best = min(best, mnW[find(1)] + w);
        }
