#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n, k; scanf("%d %d", &n, &k);
    vector<ll> b(n + 1), x(n + 2, 0);
    for (int i = 1; i <= n; i++) scanf("%lld", &b[i]);
    // scan i from n down to 1; the window starting at s = max(1, i-k+1) gives the largest weight at i
    ll A = 0, B = 0, ans = 0;                 // A = sum x_s, B = sum x_s * s over windows covering i
    for (int i = n; i >= 1; i--) {
        if (i + 1 <= n) { A -= x[i + 1]; B -= x[i + 1] * (i + 1); }   // window starting at i+1 stops covering i
        ll v = (ll)(i + 1) * A - B;              // current value at i: sum x_s * (i - s + 1)
        if (v < b[i]) {
            ll s = max(1LL, (ll)i - k + 1), w = i - s + 1;
            ll d = (b[i] - v + w - 1) / w;
            ans += d; x[s] += d; A += d; B += d * s;
        }
    }
    printf("%lld\n", ans);
}

