    for (int i = 1; i <= n; i++) { int t; ll p; scanf("%d %lld", &t, &p); (t == 1 ? kay : cat).push_back({p, i}); }
    sort(kay.rbegin(), kay.rend()); sort(cat.rbegin(), cat.rend());
