    ll best = -1; int bc = 0, bk = 0;
    for (int c = 0; c <= C && 2LL * c <= v; c++) {       // c catamarans, then as many kayaks as fit
        int k = (int)min<ll>(K, v - 2LL * c);
        if (pc[c] + pk[k] > best) { best = pc[c] + pk[k]; bc = c; bk = k; }
