#include <bits/stdc++.h>
using namespace std;
int n, m; vector<vector<int>> g; vector<array<int, 6>> ops;
void doop(int r1, int c1, int r2, int c2, int r3, int c3) {  // flip 3 cells of one 2x2 square
    g[r1][c1] ^= 1; g[r2][c2] ^= 1; g[r3][c3] ^= 1; ops.push_back({r1, c1, r2, c2, r3, c3});
}
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        scanf("%d %d", &n, &m); g.assign(n, vector<int>(m)); ops.clear();
        for (int i = 0; i < n; i++) { char s[205]; scanf("%s", s); for (int j = 0; j < m; j++) g[i][j] = s[j] - '0'; }
        // rows 0..n-3: clear each 1 with one op touching only later cells
        for (int i = 0; i + 2 < n; i++)
            for (int j = 0; j < m; j++) if (g[i][j]) {
                if (j + 1 < m) doop(i, j, i, j + 1, i + 1, j);
                else doop(i, m - 1, i + 1, m - 2, i + 1, m - 1);
            }
        // last two rows, column by column, skipping the final 2x2 block
        for (int j = 0; j + 2 < m; j++) {
            if (g[n - 2][j]) doop(n - 2, j, n - 2, j + 1, n - 1, j + 1);
            if (g[n - 1][j]) doop(n - 1, j, n - 2, j + 1, n - 1, j + 1);
        }
        // final 2x2: the four ops (each skipping one cell) span the whole space, so a subset fixes it
        int cell[4][2] = {{n - 2, m - 2}, {n - 2, m - 1}, {n - 1, m - 2}, {n - 1, m - 1}}, target = 0;
        for (int c = 0; c < 4; c++) target |= g[cell[c][0]][cell[c][1]] << c;
        for (int S = 0; S < 16; S++) {
            int vec = 0;
            for (int x = 0; x < 4; x++) if (S >> x & 1) vec ^= 15 ^ (1 << x);
            if (vec != target) continue;
            for (int x = 0; x < 4; x++) if (S >> x & 1) {
                int c[3], k = 0;
                for (int y = 0; y < 4; y++) if (y != x) c[k++] = y;
                doop(cell[c[0]][0], cell[c[0]][1], cell[c[1]][0], cell[c[1]][1], cell[c[2]][0], cell[c[2]][1]);
            }
            break;
        }
        printf("%d\n", (int)ops.size());
        for (auto &o : ops) printf("%d %d %d %d %d %d\n", o[0] + 1, o[1] + 1, o[2] + 1, o[3] + 1, o[4] + 1, o[5] + 1);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll C2(ll x) { return x * (x - 1) / 2; }
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; ll b, x; scanf("%d %lld %lld", &n, &b, &x);
        vector<ll> c(n);
        ll S = 0;
        for (auto &v : c) { scanf("%lld", &v); S += v; }
        // a race of size c split into k squads: pairs gained = C(c,2) - sum C(part,2), minimised by an even split
        vector<ll> direct(S + 2, 0), diff(S + 2, 0);
        for (ll ci : c) {
            ll base = C2(ci);
            for (ll k = 1; k <= ci; k++) {            // explicit for k <= c (total work is sum of c)
                ll q = ci / k, r = ci % k;
                ll minSum = r * C2(q + 1) + (k - r) * C2(q);
                direct[k] += b * (base - minSum);
            }
            diff[ci + 1] += b * base;                  // for k > c the race gives its full C(c,2) pairs
        }
        ll run = 0, best = LLONG_MIN;
        for (ll k = 1; k <= S; k++) {
            run += diff[k];
            best = max(best, run + direct[k] - (k - 1) * x);
        }
        printf("%lld\n", best);
    }
}

