int main() {
    int n, m; scanf("%d %d", &n, &m);
    vector<vector<int>> votes(m, vector<int>(n, 0));   // votes[j][s]: entries that match column j after shifting up s
    for (int r = 0; r < n; r++)
        for (int j = 0; j < m; j++) {
            int v; scanf("%d", &v); v--;
            if (v % m == j) {                           // value v belongs in column j, at row v / m
                int t = v / m;
                votes[j][((r - t) % n + n) % n]++;
            }
        }
    long long total = 0;
    for (int j = 0; j < m; j++) {                       // cost of column j = s shifts + cells that still mismatch
        int best = n - votes[j][0];
        for (int s = 1; s < n; s++) best = min(best, s + n - votes[j][s]);
        total += best;
    }
    printf("%lld\n", total);
}

