        if (r < m) for (int idx : L[R]) Q.push_back({r, idx});
        while (assigned[R] < T && !Q.empty()) {
            auto [pos, idx] = Q.front(); Q.pop_front();
            ll d = r - pos;                        // increments needed to move from residue (pos) to R
            nv[idx] = a[idx] + d; moves += d; assigned[R]++;
        }
    }
    printf("%lld\n", moves);
    for (int i = 0; i < n; i++) printf("%lld%c", nv[i], i + 1 == n ? '\n' : ' ');
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1e9 + 7;
int main() {
    ll n; int m; scanf("%lld %d", &n, &m);
    static char buf[1000005]; scanf("%s", buf);
    string p = buf; int L = p.size();
    vector<int> z(L, 0); z[0] = L;                       // Z-function: z[d] = longest common prefix of p and p[d..]
    for (int i = 1, l = 0, r = 0; i < L; i++) {
        if (i < r) z[i] = min(r - i, z[i - l]);
        while (i + z[i] < L && p[z[i]] == p[i + z[i]]) z[i]++;
        if (i + z[i] > r) { l = i; r = i + z[i]; }
    }
    vector<ll> y(m);
    for (auto &v : y) scanf("%lld", &v);
    bool ok = true; ll covered = 0;
    for (int i = 0; i < m; i++) {
        if (i + 1 < m) {
            ll d = y[i + 1] - y[i];
            if (d < L) { if (z[d] < L - d) ok = false; covered += d; }   // overlap: the pair must agree
            else covered += L;
        } else covered += L;
    }
    if (!ok) { puts("0"); return 0; }
    ll free_cells = n - covered, res = 1, base = 26;
    for (ll e = free_cells; e > 0; e >>= 1) { if (e & 1) res = res * base % MOD; base = base * base % MOD; }
    printf("%lld\n", res);
}
